// Validate, normalise and score an incoming lead (runs once per webhook call)
const body = $input.first().json.body || {};
const clean = (v) => (typeof v === 'string' ? v.trim() : '');

const lead = {
  name: clean(body.name),
  email: clean(body.email).toLowerCase(),
  phone: clean(body.phone),
  message: clean(body.message),
  source: clean(body.source) || 'unknown',
};

// 1) Validation
const errors = [];
if (!lead.name) errors.push('name is required');
if (!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(lead.email)) errors.push('a valid email is required');
if (lead.message.length < 10) errors.push('message must be at least 10 characters');

// 2) Rule-based lead score (0-100)
let score = 0;
const freeMail = ['gmail.com', 'yahoo.com', 'hotmail.com', 'outlook.com'];
const domain = lead.email.split('@')[1] || '';
if (domain && !freeMail.includes(domain)) score += 20;          // business email
if (lead.phone) score += 30;                                     // left a phone number
if (/\b(price|pricing|quote|demo|book|urgent|buy)\b/i.test(lead.message)) score += 30; // buying intent
if (lead.message.length >= 50) score += 20;                      // detailed message

const priority = score >= 70 ? 'hot' : score >= 40 ? 'warm' : 'cold';

return [{
  json: {
    valid: errors.length === 0,
    errors,
    lead,
    score,
    priority,
    receivedAt: new Date().toISOString(),
  },
}];
